void configurePanel(lgfx::Panel_Device& panel){auto p=panel.config();p.pin_cs=33;p.pin_rst=32;p.pin_busy=-1;p.panel_width=320;p.panel_height=480;p.memory_width=320;p.memory_height=480;p.readable=true;p.invert=prefs.getBool("invert",true);p.rgb_order=false;panel.config(p);panel.setBus(&bus);lcd.setPanel(&panel);}
void initDisplay(){auto b=bus.config();b.freq_write=16000000;b.pin_wr=4;b.pin_rd=2;b.pin_rs=15;b.pin_d0=12;b.pin_d1=13;b.pin_d2=26;b.pin_d3=25;b.pin_d4=17;b.pin_d5=16;b.pin_d6=27;b.pin_d7=14;bus.config(b);configurePanel(ili);lcd.init();uint32_t id=ili.readCommand(0xD3,1,3);Serial.printf("LCD_ID=%06lx\n",(unsigned long)id);panelName=prefs.getString("panel","");if(panelName.isEmpty())panelName=((id&0xffff)==0x7796||((id>>8)&0xffff)==0x7796||(id&0xffff)==0x9677||((id>>8)&0xffff)==0x9677)?"ST7796":"ILI9488";if(panelName=="ST7796"){configurePanel(st);lcd.init();}lcd.setRotation(0);pinMode(23,OUTPUT);ledcSetup(7,5000,8);ledcAttachPin(23,7);ledcWrite(7,menu.brightness*255/100);renderReady=renderer.begin();pinMode(18,INPUT_PULLDOWN);}
bool authorized(){if(!token.isEmpty()&&web.authenticate("admin",token.c_str()))return true;web.requestAuthentication();return false;}
bool acceptStats(JsonVariantConst doc){double now=time(nullptr),hostTime=doc["unix_time"]|0.;if(hostTime>=1700000000&&hostTime<=4102444800.)now=hostTime;if(!board::parseModel(doc,model,now))return false;if(hostTime>=1700000000&&hostTime<=4102444800.){timeval tv{time_t(hostTime),0};settimeofday(&tv,nullptr);}if(prefs.getInt("utcOffset",28800)!=model.utcOffset)prefs.putInt("utcOffset",model.utcOffset);dirty=true;return true;}
void status(JsonDocument&out){out["version"]=VERSION;out["draw_us"]=drawUs;out["max_draw_us"]=maxDrawUs;out["progress_us"]=progressUs;out["progress_updates"]=progressUpdates;out["progress_target_hz"]=60;out["loop_max_gap_us"]=loopMaxGapUs;out["render_steps"]=renderSteps;out["max_step_us"]=maxStepUs;out["render_frames"]=renderFrames;out["total_draw_us"]=totalDrawUs;out["frame_active"]=renderer.frameActive();auto ns=network.status();auto net=out["transport"].to<JsonObject>();net["mode"]=ns.connected?"tcp":"http_push";net["connected"]=ns.connected;net["peer"]=ns.peer;net["discovery"]=ns.method;net["reconnects"]=ns.reconnects;net["received"]=ns.received;net["scans"]=ns.scans;net["auth_failures"]=ns.authFailures;if(ns.received)net["staleness_ms"]=uint32_t(millis()-ns.lastReceived);out["ip"]=WiFi.localIP().toString();out["wifi"]=WiFi.status()==WL_CONNECTED;out["panel"]=panelName;out["fresh"]=board::systemFresh(model);out["host"]=model.host;for(auto&disk:model.disks){JsonObject item=out["disks"].add<JsonObject>();item["name"]=disk.name;item["free_gb"]=disk.free;item["total_gb"]=disk.total;}out["unix_time"]=int64_t(time(nullptr));out["utc_offset_seconds"]=model.utcOffset;out["display_utc_offset_seconds"]=model.followMac?model.utcOffset:28800;out["follow_mac_timezone"]=model.followMac;out["brightness_percent"]=menu.brightness;out["menu_open"]=menu.open;out["menu_info"]=menu.info;out["menu_selected"]=menu.selected;out["page"]=carousel.page;out["page_count"]=board::Carousel::pageCount(model);out["quota_pages"]=board::Carousel::quotaPages(model);out["page_duration_ms"]=board::Carousel::duration(carousel.page);out["opencode_count"]=model.opencode.total;out["paused"]=carousel.paused;out["display_buffer"]=renderReady;out["free_heap"]=ESP.getFreeHeap();out["system_sampled_at"]=board::protocol::epochSeconds(model.systemSampled);out["tasks"]["codex"]["sampled_at"]=board::protocol::epochSeconds(model.codex.sampled);out["tasks"]["codex"]["fresh"]=board::sourceFresh(model.codex,model.now);out["tasks"]["opencode"]["sampled_at"]=board::protocol::epochSeconds(model.opencode.sampled);out["tasks"]["opencode"]["fresh"]=board::sourceFresh(model.opencode,model.now);for(auto&task:model.opencode.items)out["tasks"]["opencode"]["models"].add(task.model);JsonObject quotas=out["quotas"].to<JsonObject>();  // an unbound variant must be forced to an object before children attach
for(auto&q:model.quotas){JsonObject item=quotas[q.id].to<JsonObject>();item["sampled_at"]=board::protocol::epochSeconds(q.sampled);item["fresh"]=board::quotaFresh(q,model.now);item["state"]=q.state;item["name"]=q.name;for(auto&w:q.windows){auto window=item["windows"].add<JsonObject>();window["name"]=w.label;window["label"]=w.label;window["remaining_percent"]=w.remaining;if(w.expiry)window["expires_at"]=board::protocol::epochSeconds(w.reset);else window["resets_at"]=board::protocol::epochSeconds(w.reset);}
 if(q.availability==0)item["exhausted"]=true;else if(q.availability==1)item["available"]=true;if(q.stale)item["stale"]=true;if(q.monthlyExhausted)item["monthly_exhausted"]=true;
 int ci=board::creditsWindow(q);if(ci>=0){auto&w=q.windows[ci];JsonObject cr=item["credits"].to<JsonObject>();cr["remaining"]=w.amount;cr["limit"]=w.limit;cr["unit"]=w.unit;cr["resets_at"]=board::protocol::epochSeconds(w.reset);}}}
void serialCommand(JsonDocument&doc){String cmd=doc["cmd"].as<String>();if(cmd=="provision"){String ssid=doc["ssid"].as<String>(),pass=doc["password"].as<String>(),key=doc["token"].as<String>();if(ssid.length()&&ssid.length()<=32&&key.length()>=24&&key.length()<=128&&pass.length()<=63){prefs.putString("ssid",ssid);prefs.putString("wifi",pass);prefs.putString("token",key);token=key;network.setKey(token);WiFi.begin(ssid.c_str(),pass.c_str());Serial.println("{\"provision\":\"accepted\"}");}}
 else if(cmd=="status"){JsonDocument out;status(out);serializeJson(out,Serial);Serial.println();}
 else if(cmd=="panel"){String p=doc["model"].as<String>();if(p=="ILI9488"||p=="ST7796"){prefs.putString("panel",p);prefs.putBool("invert",doc["invert"]|true);Serial.println("{\"panel\":\"saved\"}");delay(100);ESP.restart();}}
 else if(cmd=="stats"||doc["schema_version"].is<int>()){bool ok=acceptStats(doc.as<JsonVariantConst>());if(!ok)Serial.println("{\"error\":\"invalid_snapshot\"}");}}
void handleSerial(){while(Serial.available()){char c=Serial.read();if(c=='\n'){if(!serialOverflow){JsonDocument doc;if(!deserializeJson(doc,serialLine))serialCommand(doc);}serialLine="";serialOverflow=false;}else if(!serialOverflow){if(serialLine.length()<MAX_BODY)serialLine+=c;else{serialLine="";serialOverflow=true;}}}}
void setup(){Serial.begin(115200);prefs.begin("statusboard",false);model.utcOffset=prefs.getInt("utcOffset",28800);model.followMac=prefs.getBool("followMac",true);model.version=VERSION;model.ssid=prefs.getString("ssid","").c_str();menu.brightness=prefs.getInt("brightness",100);if(menu.brightness<25||menu.brightness>100)menu.brightness=100;carousel.paused=prefs.getBool("paused",false);token=prefs.getString("token","");initDisplay();WiFi.mode(WIFI_STA);WiFi.setSleep(false);WiFi.setAutoReconnect(true);String ssid=prefs.getString("ssid",""),pass=prefs.getString("wifi","");if(ssid.length())WiFi.begin(ssid.c_str(),pass.c_str());configTime(0,0,"ntp.aliyun.com","time.apple.com","pool.ntp.org");const char*headers[]={"Authorization"};web.collectHeaders(headers,1);
 web.on("/",HTTP_GET,[](){if(!authorized())return;web.send(200,"text/html","<!doctype html><meta charset=utf-8><title>信息牌 OTA</title><h1>信息牌</h1><p><a href=/status>查看状态</a></p><p>上传 firmware.bin，更新时保持供电。</p><form method=post action=/update enctype=multipart/form-data><input type=file name=firmware accept=.bin required><button>更新固件</button></form>");});
 web.on("/status",HTTP_GET,[](){if(!authorized())return;JsonDocument d;status(d);String s;serializeJson(d,s);web.send(200,"application/json",s);});
 web.on("/stats",HTTP_POST,[](){if(!authorized())return;if(web.arg("plain").length()>MAX_BODY){web.send(413);return;}JsonDocument d;if(deserializeJson(d,web.arg("plain"))||!acceptStats(d.as<JsonVariantConst>())){web.send(400);return;}web.send(200,"application/json","{\"ok\":true}");});
 web.on("/update",HTTP_POST,[](){if(!authorized())return;bool ok=otaOK&&!Update.hasError();web.send(ok?200:400,"text/plain",ok?"Updated; rebooting":"Update failed");if(ok){delay(300);ESP.restart();}},[](){if(token.isEmpty()||!web.authenticate("admin",token.c_str()))return;HTTPUpload&u=web.upload();if(u.status==UPLOAD_FILE_START)otaOK=Update.begin(UPDATE_SIZE_UNKNOWN);else if(u.status==UPLOAD_FILE_WRITE&&otaOK){if(Update.write(u.buf,u.currentSize)!=u.currentSize){Update.abort();otaOK=false;}}else if(u.status==UPLOAD_FILE_END&&otaOK)otaOK=Update.end(true);else if(u.status==UPLOAD_FILE_ABORTED){Update.abort();otaOK=false;}});
 web.begin();if(renderReady)renderer.render(model,carousel,millis());network.begin(token);Serial.println("READY");}
void loop(){uint32_t loopUs=micros();if(lastLoopUs)loopMaxGapUs=std::max(loopMaxGapUs,uint32_t(loopUs-lastLoopUs));lastLoopUs=loopUs;handleSerial();web.handleClient();std::string incoming;if(network.takeSnapshot(incoming)){JsonDocument doc;if(incoming.size()<=MAX_BODY&&!deserializeJson(doc,incoming))acceptStats(doc.as<JsonVariantConst>());}uint32_t ms=millis();model.now=time(nullptr);model.ip=WiFi.localIP().toString().c_str();bool now=WiFi.status()==WL_CONNECTED;static bool connected=false;if(now!=connected){connected=now;model.wifi=now;dirty=true;if(now){Serial.println("IP="+WiFi.localIP().toString());}}
 if(!now&&uint32_t(ms-lastReconnect)>30000){lastReconnect=ms;WiFi.reconnect();}
 int action=button.tick(digitalRead(18)==HIGH,ms);if(action){int changed=menu.action(action,model,carousel,ms);if(changed&1){ledcWrite(7,menu.brightness*255/100);prefs.putInt("brightness",menu.brightness);}if(changed&2)prefs.putBool("followMac",model.followMac);if(changed&4)prefs.putBool("paused",menu.savedPaused);dirty=true;}if(menu.tick(carousel,ms))dirty=true;
 int page=carousel.page;if(!menu.open)carousel.tick(model,ms);if(page!=carousel.page)dirty=true;
 if(renderReady&&!renderer.frameActive()&&(dirty||uint32_t(ms-lastPaint)>=1000)){
  if(renderer.startFrame(model,carousel,ms,&menu)){dirty=false;lastPaint=ms;frameDrawUs=0;}
 }
 if(renderReady&&renderer.frameActive()){uint32_t started=micros();bool complete=renderer.renderStep();uint32_t spent=micros()-started;++renderSteps;maxStepUs=std::max(maxStepUs,spent);frameDrawUs+=spent;totalDrawUs+=spent;if(complete){++renderFrames;drawUs=frameDrawUs;maxDrawUs=std::max(maxDrawUs,drawUs);}}
 // Sixty target updates per second with a 16/17 ms cadence. The renderer skips
 // identical fractional coverage, so this counts only actual display writes.
 static uint32_t progressPhase=0;ms=millis();if(renderReady&&!menu.open&&uint32_t(ms-lastProgress)>=(progressPhase%3==0?16:17)){uint32_t started=micros();if(renderer.renderProgress(carousel,ms))++progressUpdates;progressUs=micros()-started;lastProgress=ms;++progressPhase;}delay(1);}
